-- Canarias 1400: unique units and buildings of the seven peoples, cloned from the stock rows at load time (generated by text/build_text.py).
-- The donor civilizations' own uniques are unhooked; stock 3D models, techs and upgrade paths are kept.

-- Sigone (TENERIFE): UNIT_SPEARMAN
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_SPEARMAN';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_CAN1400_SIGONE', Description = 'TXT_KEY_UNIT_CAN1400_SIGONE', Civilopedia = 'TXT_KEY_CIV5_CAN1400_SIGONE_TEXT', Strategy = 'TXT_KEY_UNIT_CAN1400_SIGONE_STRATEGY', Help = 'TXT_KEY_UNIT_CAN1400_SIGONE_HELP', Combat = Combat + 1;

-- Tirador (GRANCANARIA): UNIT_ARCHER
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_ARCHER';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_CAN1400_TIRADOR', Description = 'TXT_KEY_UNIT_CAN1400_TIRADOR', Civilopedia = 'TXT_KEY_CIV5_CAN1400_TIRADOR_TEXT', Strategy = 'TXT_KEY_UNIT_CAN1400_TIRADOR_STRATEGY', Help = 'TXT_KEY_UNIT_CAN1400_TIRADOR_HELP', Combat = Combat + 1, RangedCombat = RangedCombat + 1;

