CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_SPEARMAN';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_CAN1400_AHEPA', Description = 'TXT_KEY_UNIT_CAN1400_AHEPA', Civilopedia = 'TXT_KEY_CIV5_CAN1400_AHEPA_TEXT', Strategy = 'TXT_KEY_UNIT_CAN1400_AHEPA_STRATEGY', Help = 'TXT_KEY_UNIT_CAN1400_AHEPA_HELP', Cost = 42;

