CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_WARRIOR';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_CAN1400_GUARDIA', Description = 'TXT_KEY_UNIT_CAN1400_GUARDIA', Civilopedia = 'TXT_KEY_CIV5_CAN1400_GUARDIA_TEXT', Strategy = 'TXT_KEY_UNIT_CAN1400_GUARDIA_STRATEGY', Help = 'TXT_KEY_UNIT_CAN1400_GUARDIA_HELP', Combat = Combat;

-- replace the donors' unique units
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_SHOSHONE';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_EGYPT';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_ETHIOPIA';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_INCA';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_CELTS';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_MOROCCO';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_CARTHAGE';

