UPDATE tmp_b SET ID = (SELECT MAX(ID) + 1 FROM Buildings), Type = 'BUILDING_CAN1400_TAGOROR', Description = 'TXT_KEY_BUILDING_CAN1400_TAGOROR', Civilopedia = 'TXT_KEY_CIV5_CAN1400_TAGOROR_TEXT', Strategy = 'TXT_KEY_BUILDING_CAN1400_TAGOROR_STRATEGY', Help = 'TXT_KEY_BUILDING_CAN1400_TAGOROR_HELP', GoldMaintenance = 0, Happiness = 1;

