-- replace the donors' unique buildings
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_SHOSHONE';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_EGYPT';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_ETHIOPIA';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_INCA';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_CELTS';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_MOROCCO';
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_CARTHAGE';
-- No horses on the islands: every mounted unit, every unit that needs Horses and the stables move to a technology nobody can research,
-- so that neither the peoples nor the barbarians ever field them.
UPDATE Units SET PrereqTech = 'TECH_ASTRONOMY' WHERE CombatClass = 'UNITCOMBAT_MOUNTED' OR Type IN (SELECT UnitType FROM Unit_ResourceQuantityRequirements WHERE ResourceType = 'RESOURCE_HORSE');
UPDATE Buildings SET PrereqTech = 'TECH_ASTRONOMY' WHERE BuildingClass = 'BUILDINGCLASS_STABLE';
